# /etc/nginx/conf.d/app.conf
location / {
    proxy_pass http://app_backend;

    # Buffering: tampung response backend dulu, lalu kirim ke klien
    proxy_buffering      on;
    proxy_buffer_size    8k;     # buffer pertama (header response)
    proxy_buffers        8 16k;  # 8 buffer x 16 KB = 128 KB untuk body
    proxy_busy_buffers_size 32k; # maks buffer yang boleh dikirim sekaligus
    proxy_max_temp_file_size 0;  # jangan tulis response ke disk (hindari I/O)

    # Request body dari klien: buffer di memory, jangan stream mentah
    client_body_buffer_size 128k;
    client_max_body_size    20m;
}

# /etc/nginx/conf.d/app.conf
location / {
    proxy_pass http://app_backend;

    proxy_connect_timeout 5s;   # gagal cepat kalau backend tidak merespons
    proxy_read_timeout    30s;  # tunggu response backend maks 30 detik
    proxy_send_timeout    30s;
    client_body_timeout   10s;
    send_timeout          30s;

    # Endpoint khusus yang memang lama (export laporan, dsb.)
    # taruh di location terpisah dengan timeout lebih longgar:
}

location /api/export {
    proxy_pass http://app_backend;
    proxy_read_timeout 300s;  # export boleh lama, tapi hanya di endpoint ini
}

# /etc/nginx/conf.d/app.conf
upstream app_backend {
    server 127.0.0.1:3000;
    server 127.0.0.1:3001;
    keepalive 32;          # 32 koneksi idle per worker ke backend
    keepalive_timeout 60s;
    keepalive_requests 10000;
}

server {
    listen 443 ssl;
    server_name api.contoh.id;

    location / {
        proxy_pass http://app_backend;
        proxy_http_version 1.1;            # keepalive butuh HTTP/1.1
        proxy_set_header Connection "";    # hapus "Connection: close"

        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

# Cache HANYA untuk response yang aman di-cache (GET, status 200)
proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=api_cache:100m
                 max_size=1g inactive=60m use_temp_path=off;

location /api/public/ {
    proxy_pass http://app_backend;
    proxy_cache api_cache;
    proxy_cache_valid 200 5m;   # cache response 200 selama 5 menit
    proxy_cache_valid 404 1m;
    proxy_cache_use_stale error timeout updating;  # sajikan cache lama saat backend down
    add_header X-Cache-Status $upstream_cache_status;  # HIT / MISS / BYPASS
}

# /etc/nginx/conf.d/app.conf
upstream app_backend {
    server 10.0.0.11:3000 max_fails=3 fail_timeout=30s;
    server 10.0.0.12:3000 max_fails=3 fail_timeout=30s;
    server 10.0.0.13:3000 backup;  # hanya dipakai kalau dua server utama down
    keepalive 32;
}

location / {
    proxy_pass http://app_backend;
    # Coba server lain kalau: error koneksi, timeout, atau 502/503
    proxy_next_upstream error timeout http_502 http_503;
    proxy_next_upstream_tries 3;      # maks 3 percobaan total
    proxy_next_upstream_timeout 10s;  # total waktu failover maks 10 detik
}
